import { StatusBar } from "march/ui"
import { gitBranch, alertTriangle } from "march/icons"

// düzenleyici durum çubuğu: dal, hatalar, imleç satırı; kaydet düğmesi durumu değiştirir
export function EditorStatus() {
  let $saving = false
  let $line = 1
  return <StatusBar label="Editör durumu" items={[
    { id: "branch", icon: gitBranch, text: "main", priority: 5 },
    { id: "problems", icon: alertTriangle, text: "0 hata", priority: 3 },
    { id: "pos", side: "end", text: () => `Sa ${$line}`, title: "Sonraki satır", onSelect: () => $line++, priority: 4 },
    { id: "save", side: "end", text: () => ($saving ? "Kaydediliyor…" : "Kaydet"), tone: () => ($saving ? "busy" : "success"), onSelect: () => { $saving = true; setTimeout(() => $saving = false, 800) }, live: true, priority: 9 },
  ]} />
}

import { StatusBar } from "march/ui"
import { bell, moreHorizontal } from "march/icons"

// StatusBar'ın özellikleri: items (id, text, icon, side, tone, title, onSelect, command, priority, live), label,
// moreLabel, moreIcon, overflow, dot (kendi işaretin), pulse, class
export function StatusBarLab() {
  let $count = 0
  return <div sx={{ flex: "col", gap: 2 }}>
    <StatusBar class="lab-bar" label="Durum" moreLabel="Daha fazla" moreIcon={moreHorizontal} pulse={false}
      dot={(tone: () => string) => <b>{() => (tone() === "busy" ? "◌" : "◆")}</b>}
      items={[
        { id: "count", text: () => `${$count} tık`, title: "Say", onSelect: () => $count++ },
        { id: "bell", side: "end", icon: bell, text: "2", title: "Bildirimler", tone: "busy", priority: 2 },
        { id: "ok", side: "end", text: "Hazır", tone: "success", live: true },
      ]} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { StatusBarLab } from "./StatusBarLab.tsx"

// StatusBarLab'in testleri: kaydedince Testler sekmesinde çalışır
test("öğeler çizilir, çubuğun adı label", () => {
  const s = renderTest(() => <StatusBarLab />)
  expect(s.sees("Hazır")).toBe(true)
  expect(s.get(".lab-bar")?.getAttribute("aria-label")).toBe("Durum")
})

test("onSelect'li öğe düğmedir ve basılınca çalışır", async () => {
  const s = renderTest(() => <StatusBarLab />)
  await s.click("0 tık")
  expect(s.sees("1 tık")).toBe(true)
})
